                “description”: “折线图，适合展示趋势变化”
            })
       
        if “comparison” in str(analysis).lower():
            suggestions.append({
                “type”: “bar”,
                “description”: “柱状图，适合对比不同类别”
            })
       
        suggestions.append({
            “type”: “table”,
            “description”: “数据表格，展示详细数据”
        })
       
        return suggestions
   
    def generate_report(self, analysis, charts):
